      {"page_number": 10, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p10_c1"},
      {"page_number": 49, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p49_c1"}
    ]
  },
  {
    "alert_id": "EX4_002",
    "title": "Carbamazepine toxicity with hyponatremia",
    "message": "Patient has carbamazepine level 14 mcg/mL (therapeutic 4–12), with nystagmus, ataxia, tremor, dizziness, and headaches. Hyponatremia (Na 128 mmol/L) is also consistent with carbamazepine toxicity. The clinician plans dose reduction and repeat level, which is appropriate. Sodium valproate is co-prescribed; valproate can potentiate carbamazepine toxicity via CYP inhibition and protein-binding displacement. Concurrent ALT 68 U/L may reflect hepatic effects of either antiepileptic.",
    "issue_type": "toxicity",
    "severity": "high",
    "recommended_action": "Reduce carbamazepine dose, repeat level and sodium. Monitor LFTs. Consider valproate interaction. Re-evaluate antiepileptic regimen in light of DTG contraindication.",
    "citations": []
  },
  {
    "alert_id": "EX4_003",
    "title": "Detectable viral load needs adherence and resistance workup",
    "message": "Guidelines state virological monitoring provides early indication of treatment failure and the need to switch therapy. A repeat viral load >1000 copies/mL suggests treatment failure and warrants HIV drug resistance testing after ruling out adherence issues. Patient's VL is 1,240 copies/mL after prior suppression. The clinician's plan does not address the detectable viral load beyond noting uncertainty about the cause. The carbamazepine–DTG interaction is a likely pharmacokinetic driver, but adherence should still be assessed and a repeat VL planned.",
    "issue_type": "guideline_deviation",
    "severity": "high",
    "recommended_action": "Address carbamazepine–DTG interaction first. Assess adherence, repeat viral load in 2–3 months after correcting interaction, and consider genotype testing if VL remains >1000.",
    "citations": [
      {"page_number": 12, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p12_c1"},
      {"page_number": 50, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p50_c2"}
    ]
  },
  {
    "alert_id": "EX4_004",
    "title": "Elevated ALT with two hepatotoxic drugs",
    "message": "ALT is 68 U/L with both sodium valproate and carbamazepine prescribed. Both antiepileptics are known to cause hepatotoxicity. Guidelines note that TDF can cause liver toxicity and recommend LFTs when deranged liver enzymes are present. DTG is generally well-tolerated hepatologically. The elevated ALT more likely reflects antiepileptic effects, but TDF contribution cannot be excluded. LFT monitoring is indicated given the concurrent use of two hepatotoxic agents.",
    "issue_type": "toxicity",
    "severity": "moderate",
    "recommended_action": "Monitor LFTs regularly. If ALT rises further or exceeds 3× upper limit of normal, consider dose adjustment or substitution of the offending antiepileptic.",
    "citations": [
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__p37_c1"}
    ]
  }
]

